// The control panel, as data.
//
// Every tunable is here with its range and a word about it, so adding one means
// editing this file and `types.ts` and nothing else - the panel draws whatever
// this says.

import { StarmapSettings } from './types';

export type SliderSection = 'forces' | 'display' | 'motion' | 'sound';

export interface SliderDef {
    sec: SliderSection;
    key: keyof StarmapSettings;
    label: string;
    min: number;
    max: number;
    step: number;
    // What it does, for the tooltip. Only where the label does not say it.
    hint?: string;
}

