export const SECTIONS: SliderSection[] = ['forces', 'display', 'motion', 'sound'];

// How a value is written next to its slider. Two of them are small enough that
// rounding would show every step as the same number.
export function formatValue(key: keyof StarmapSettings, v: number): string {
    if (key === 'center') return v.toFixed(5);
    if (key === 'spring') return v.toFixed(3);
    if (v >= 10) return String(Math.round(v));
    return v.toFixed(2);
}
