// A rendered heading, in the theme the exporter rendered it for.
//
// The shadow root is the whole point. A theme's stylesheet is written for a page
// it owns - it says things about `body`, about `h1`, about `pre` - and dropping
// that into the app's own markup would restyle the app. In a shadow root the
// theme reaches the heading and stops there, and the heading still grows to
// whatever height it needs, which is what an iframe would have cost.
//
// Where no theme has been asked for there is nothing to isolate, and the html is
// rendered inline with the app's own styling instead, the way it always was.

import * as React from 'react';
import Box from '@mui/joy/Box';

import { shadowCss, PAGE_CLASS } from '../htmlframe';

// The app's own treatment of a bare fragment: no theme, so this is what keeps it
// from looking like unstyled html in a styled dialog.
const PLAIN_SX = {
    '& h1, & h2, & h3, & h4': { mt: 1.5, mb: 0.5 },
    '& p': { my: 0.5 },
    '& ul, & ol': { pl: 2.5 },
    '& pre': {
        backgroundColor: 'background.level1', p: 1, borderRadius: 'sm',
        overflow: 'auto', fontSize: '12px',
    },
    '& code': { fontSize: '12px' },
    '& a': { color: 'primary.plainColor' },
    '& img': { maxWidth: '100%', borderRadius: 8 },
    fontSize: '14px',
    lineHeight: 1.6,
} as const;

export default function ThemedHtml(props: {
    html: string;
    // The theme's stylesheet, as the server handed it over. Empty means there is
    // no theme and the fragment is shown with the app's own styling.
    style?: string;
    // Extra rules for the shadow root, for a caller that wants to hide part of
    // what it rendered. Appended last, so they win.
    extraCss?: string;
    // Styling for the plain, un-themed case only - a themed page is inside a
    // shadow root where none of it would reach.
    sx?: any;
}) {
    const hostRef = React.useRef<HTMLDivElement | null>(null);
    const rootRef = React.useRef<ShadowRoot | null>(null);
    const styleRef = React.useRef<HTMLStyleElement | null>(null);
    const pageRef = React.useRef<HTMLDivElement | null>(null);

    const themed = (props.style || '') !== '';
    const css = React.useMemo(
        () => (themed ? `${shadowCss(props.style || '')}\n${props.extraCss || ''}` : ''),
        [themed, props.style, props.extraCss],
    );

    // The root is attached once and then written to. Re-attaching on every
    // render would throw the scroll position away five seconds into reading,
    // which is how often the popup refetches.
    React.useEffect(() => {
        if (!themed) return;
        const host = hostRef.current;
        if (!host) return;
        if (rootRef.current === null) {
            // attachShadow throws if one is already there, which happens when
            // React reuses the node across a remount.
            rootRef.current = host.shadowRoot || host.attachShadow({ mode: 'open' });
            const style = document.createElement('style');
            const page = document.createElement('div');
            page.className = PAGE_CLASS;
            rootRef.current.append(style, page);
            styleRef.current = style;
            pageRef.current = page;
        }
        if (styleRef.current && styleRef.current.textContent !== css) {
            styleRef.current.textContent = css;
        }
        if (pageRef.current && pageRef.current.innerHTML !== props.html) {
            pageRef.current.innerHTML = props.html;
        }
    }, [themed, css, props.html]);

    if (themed) return <Box ref={hostRef} />;

    return <Box sx={{ ...PLAIN_SX, ...(props.sx || {}) }} dangerouslySetInnerHTML={{ __html: props.html }} />;
}
